const api = {
  async post(url, body) {
    if (url.includes('/auth/login')) {
      const { email } = body;
      let userData = DEMO_USERS[email?.toLowerCase()];

      try {
        const { data: dbUser } = await supabase
          .from('users')
          .select('*, employee:employees(*, department:departments(*), designation:designations(*))')
          .eq('email', email)
          .single();

        if (dbUser) {
          userData = {
            id: dbUser.id,
            email: dbUser.email,
            role: dbUser.role,
            firstName: dbUser.employee?.first_name || (dbUser.role === 'admin' ? 'Admin' : 'User'),
            lastName: dbUser.employee?.last_name || '',
            employeeId: dbUser.employee?.employee_id || 'EMP000',
            department: dbUser.employee?.department?.name || 'General',
            designation: dbUser.employee?.designation?.title || 'Staff',
            profilePicture: dbUser.employee?.profile_picture || null,
          };
        }
      } catch (e) {}

      if (!userData && email) {
        userData = {
          id: 'b0000000-0000-0000-0000-000000000000',
          email,
          role: email.includes('admin') ? 'admin' : (email.includes('hr') || email.includes('priya') ? 'hr' : 'employee'),
          firstName: email.split('@')[0].split('.')[0],
          lastName: email.split('@')[0].split('.')[1] || 'User',
          employeeId: 'EMP' + Math.floor(100 + Math.random() * 900),
          department: 'Engineering',
          designation: 'Software Developer',
        };
      }

      return { data: { success: true, data: userData, token: 'demo-jwt-token' } };
    }

    return { data: { success: true, data: body } };
  },

  async get(url) {
    if (url.includes('/auth/me')) {
      const saved = localStorage.getItem('user');
      const u = saved ? JSON.parse(saved) : DEMO_USERS['admin@kaaryasetu.com'];
      return { data: { success: true, data: u } };
    }

    if (url.includes('/employees')) {
      try {
        const { data: emps } = await supabase
          .from('employees')
          .select('*, department:departments(name), designation:designations(title)');

        if (emps && emps.length > 0) {
          const formatted = emps.map(e => ({
            _id: e.id,
            id: e.id,
            employeeId: e.employee_id,
            firstName: e.first_name,
            lastName: e.last_name,
            email: e.email,
            phone: e.phone,
            department: e.department,
            designation: e.designation?.title || 'Staff',
            status: e.status,
            joiningDate: e.joining_date
          }));
          return { data: { success: true, data: formatted } };
        }
      } catch (e) {}

      return { data: { success: true, data: MOCK_EMPLOYEES } };
    }

    if (url.includes('/attendance')) {
      return { data: { success: true, data: MOCK_ATTENDANCE } };
    }

    if (url.includes('/leaves')) {
      return { data: { success: true, data: MOCK_LEAVES } };
    }

    if (url.includes('/payroll')) {
      return { data: { success: true, data: MOCK_PAYROLL } };
    }

    if (url.includes('/departments')) {
      return { data: { success: true, data: MOCK_DEPTS } };
    }

    if (url.includes('/recruitment')) {
      return { data: { success: true, data: MOCK_RECRUITMENT } };
    }

    if (url.includes('/feedback')) {
      return { data: { success: true, data: MOCK_FEEDBACK } };
    }

    if (url.includes('/reports/dashboard')) {
      return {
        data: {
          success: true,
          data: {
            stats: {
              totalEmployees: 200,
              presentToday: 184,
              absentToday: 9,
              onLeave: 7,
              pendingLeaves: 4,
              pendingCorrections: 2
            },
            recentEmployees: MOCK_EMPLOYEES.slice(0, 10),
            departmentBreakdown: [
              { department: 'Engineering', count: 80 },
              { department: 'Human Resources', count: 25 },
              { department: 'Finance', count: 30 },
              { department: 'Marketing', count: 35 },
              { department: 'Sales', count: 30 }
            ]
          }
        }
      };
    }

    if (url.includes('/reports/attendance-trend')) {
      return {
        data: {
          success: true,
          data: [
            { month: 'Mar', present: 185, absent: 10, leave: 5 },
            { month: 'Apr', present: 188, absent: 8, leave: 4 },
            { month: 'May', present: 182, absent: 12, leave: 6 },
            { month: 'Jun', present: 190, absent: 6, leave: 4 },
            { month: 'Jul', present: 186, absent: 9, leave: 5 },
            { month: 'Aug', present: 184, absent: 9, leave: 7 }
          ]
        }
      };
    }

    if (url.includes('/holidays')) {
      return {
        data: {
          success: true,
          data: [
            { id: '1', name: 'Ganesh Chaturthi', date: '2026-08-22', type: 'Regional' },
            { id: '2', name: 'Gandhi Jayanti', date: '2026-10-02', type: 'National' },
            { id: '3', name: 'Diwali', date: '2026-10-19', type: 'National' },
            { id: '4', name: 'Christmas Day', date: '2026-12-25', type: 'National' }
          ]
        }
      };
    }

    if (url.includes('/announcements')) {
      return {
        data: {
          success: true,
          data: [
            { id: '1', title: 'Welcome to KaaryaSetu HR Portal', priority: 'high', content: 'Centralized 200+ employee portal live.', isNew: true, createdAt: '2026-08-20' },
            { id: '2', title: 'Annual Performance Review 2026', priority: 'medium', content: 'Q3 appraisal cycles initiated.', isNew: false, createdAt: '2026-08-18' }
          ]
        }
      };
    }

    return { data: { success: true, data: [] } };
  },

  async put(url, body) {
    return { data: { success: true, data: body } };
  },

  async delete(url) {
    return { data: { success: true } };
  }
};

export default api;
